inline constexpr char16_t ubuntuBase[]=u"http://releases.ubuntu.com/26.04/";
// The system image must be the very one the network kernel and installer
// were built for (the installer compares identifiers and refuses another -
// seen with a 26.04 image against the 26.04.1 installer). Ubuntu names it in
// its own network boot configuration next to them; Charon reads it there.
inline bool UbuntuImageAddress(char* out,size_t capacity) {
    static char16_t url[300];static Memory config;out[0]=0;
    Set(url,300,ubuntuBase);Cat(url,300,u"netboot/amd64/grub/grub.cfg");
    if(!FetchToMemory(url,config,0,T(u"konfigurację instalatora Ubuntu",u"the Ubuntu installer's configuration")))return false;
    static const char key[]="iso-url=";const size_t keyLength=sizeof(key)-1;
    for(size_t i=0;i+keyLength<config.size && !out[0];++i) {
        size_t m=0;while(m<keyLength && char(config.data[i+m])==key[m])++m;
        if(m!=keyLength)continue;
        size_t k=0;
        for(size_t j=i+keyLength;j<config.size && config.data[j]>' ' && config.data[j]<127 && k+1<capacity;++j)out[k++]=char(config.data[j]);
        out[k]=0;
    }
    Free(config);
    size_t n=0;while(out[n])++n;
    const bool http=out[0]=='h' && out[1]=='t' && out[2]=='t' && out[3]=='p';
    return http && n>12 && out[n-4]=='.' && out[n-3]=='i' && out[n-2]=='s' && out[n-1]=='o';
}
// cloud-init user-data with the autoinstall section.
// r410 (kd): dataFstab = the fstab line of a plan's shared data partition (nullptr: none).
inline void UbuntuUserData(Text& y,bool largest,const char* dataFstab=nullptr) {
    y.Line("#cloud-config");
    y.Line("# Written by Charon from spoken answers.");
    y.Line("autoinstall:");
    y.Line("  version: 1");
    y.Line("  locale: ",ask::Get("locale"),".UTF-8");
    y.Line("  keyboard: {layout: ",ask::Get("keyboard"),"}");
    y.Line("  timezone: ",ask::Get("timezone"));
    y.Line("  identity:");
    y.Line("    hostname: \"",ask::Get("hostname"),"\"");   // r409: quoted - a name such as no, on or null is a string, not a YAML truth value
    y.Line("    realname: \"",ask::Get("fullname"),"\"");
    y.Line("    username: \"",ask::Get("user"),"\"");
    y.Line("    password: \"",ask::Get("hash"),"\"");
    y.Line("  ssh: {install-server: ",ask::Is("ssh","yes")?"true":"false","}");
    y.Line("  updates: ",ask::Is("updates","yes")?"all":"security");
    y.Line("  storage:");
    y.Line("    layout:");
    y.Line("      name: direct");
    if(ask::Is("diskmode","free"))y.Line("      mode: use_gap");
    y.Line("      match: {size: ",largest?"largest":"smallest","}");
    y.Add("  packages: [efibootmgr");
    {static char packages[200];ReaderPackages(packages,sizeof(packages),ask::Any("desktop"));y.Add(packages);}
    for(const auto& c:ubuntuDesktops)if(ask::Has("desktop",c.value)) {y.Add(", ");y.Add(c.value);}
    y.Line("]");
    // Before any disk is touched: Charon and the scripts go into memory
    // (/run is a RAM file system), because the disk they are on may be the
    // one that gets erased. The borrowed volume label is given back here too.
    y.Line("  early-commands:");
    y.Line("    - mkdir -p /run/charon/EFI /mnt/charon; for c in $(blkid -c /dev/null -t TYPE=iso9660 -o device); do l=$(losetup -f -P -r --show $c 2>/dev/null) && echo $l >> /run/charon/loops; done; udevadm settle 2>/dev/null; for d in $(blkid -c /dev/null -t TYPE=vfat -o device); do mount -o ro $d /mnt/charon 2>/dev/null || continue; [ -f /mnt/charon/EFI/HAK/CHARONVOICE.EFI ] && [ ! -d /run/charon/EFI/HAK ] && cp -r /mnt/charon/EFI/HAK /run/charon/EFI/; [ -f /mnt/charon/EFI/HAK/CHARONVOICE.EFI ] && [ ! -f /run/charon/EFI/HAK/HAKBOOT.EFI ] && [ -f /mnt/charon/EFI/BOOT/BOOTX64.EFI ] && cp /mnt/charon/EFI/BOOT/BOOTX64.EFI /run/charon/EFI/HAK/HAKBOOT.EFI; [ -d /mnt/charon/charon-install/ubuntu ] && cp /mnt/charon/charon-install/ubuntu/*.sh /mnt/charon/charon-install/ubuntu/*.wav /mnt/charon/charon-install/ubuntu/label.txt /mnt/charon/charon-install/ubuntu/charon-tone /mnt/charon/charon-install/ubuntu/voice.conf /mnt/charon/charon-install/ubuntu/network.conf /run/charon/ 2>/dev/null; [ -f /mnt/charon/charon-install/ubuntu/network.conf ] && mount -o remount,rw /mnt/charon 2>/dev/null && rm -f /mnt/charon/charon-install/ubuntu/network.conf; umount /mnt/charon; done; for l in $(cat /run/charon/loops 2>/dev/null); do losetup -d $l; done; true");   // r410 (kd, T10 runs kd1/kd2): HAKBOOT.EFI = the running Charon (EFI/BOOT/BOOTX64.EFI of its medium) when EFI/HAK has none, as images::CharonOnto does - else install-charon.sh registers no "Charon" boot entry; Charon on a CD/DVD (hybrid ISO: its FAT is MBR partition 1, type EF, which Linux does not scan on an optical drive) is reached through a read-only loop device with partition scan (losetup -P); r409: network.conf (the Wi-Fi key) is taken into memory and removed from the partition
    y.Line("    - rm -f /run/charon/EFI/HAK/continue.bin /run/charon/EFI/HAK/continue-set /run/charon/EFI/HAK/installed-by.txt /run/charon/EFI/HAK/reader-only; true");
    // r409: the copy above is made by cp -r, which takes all of \EFI\HAK: saved answer sets and plan state are removed
    // from it at once, by the list every other copy of \EFI\HAK uses (CharonPrivate.h), whatever the case of the names.
    // r409: except when this installation erases Charon's own disk (CarryHome, CharonWsInstall.h): then they are carried
    // to the new EFI partition, and only network.conf (another installation's Wi-Fi key) is removed.
    if(CarryHome())y.Line("    - rm -f /run/charon/EFI/HAK/network.conf; true");
    else {y.Add("    - ");hakprivate::ShellRemove("/run/charon/EFI/HAK",[&](const char* piece) {y.Add(piece);});y.Line("; true");}
    if(ask::Is("speech","yes"))y.Line("    - echo ",ask::Get("locale")," > /run/charon/lang.txt; sh /run/charon/live-speech.sh > /run/charon/live-speech.log 2>&1; true");
    y.Line("    - L=$(cat /run/charon/label.txt 2>/dev/null); for d in /dev/disk/by-label/CIDATA; do [ -e $d ] && [ -n \"$L\" ] && fatlabel $d \"$L\"; done; true");
    // r410 (kd, run kd4): in a plan a failed installation reports the step as failed to Charon (EFI/HAK/plan/stepN.failed
    // with the end of the installer's log, install-charon.sh plan-failed finds the plan's EFI partition itself) and
    // restarts, so that Charon asks "try again / skip / stop" instead of the installer waiting at its error screen.
    // error-commands: run in the installer environment after the installation has failed (autoinstall reference).
    if(ask::Any("plan")) {
        y.Line("  error-commands:");
        y.Line("    - sh /run/charon/install-charon.sh plan-failed \"Ubuntu installer error\" /var/log/installer/subiquity-server-debug.log; true");
        y.Line("    - sync; sleep 5; systemctl reboot --force; true");
    }
    y.Line("  late-commands:");
    y.Line("    - mkdir -p /target/boot/efi/EFI/HAK /target/var/lib/charon");
    y.Line("    - cp -r /run/charon/EFI/HAK/. /target/boot/efi/EFI/HAK/ 2>/dev/null; cp /run/charon/*.sh /run/charon/*.wav /run/charon/charon-tone /run/charon/voice.conf /target/var/lib/charon/ 2>/dev/null; chmod 755 /target/var/lib/charon/charon-tone; true");
    y.Line("    - curtin in-target -- sh /var/lib/charon/install-charon.sh || true");
    // r409: the Wi-Fi connection chosen in Charon, when there is one (network.sh came with the other scripts).
    y.Line("    - if [ -f /run/charon/network.conf ]; then cp /run/charon/network.conf /target/var/lib/charon/; chmod 600 /target/var/lib/charon/network.conf; curtin in-target -- sh /var/lib/charon/network.sh apply; fi; true");
    // r410: the detailed answers (the volume names the file answers-env.sh so that the copies above take it along).
    if(detailed::Carried())
        y.Line("    - if [ -f /target/var/lib/charon/answers-env.sh ]; then mv /target/var/lib/charon/answers-env.sh /target/var/lib/charon/answers.env; chmod 600 /target/var/lib/charon/answers.env; curtin in-target -- sh /var/lib/charon/personal.sh install; fi; true");
    if(ask::Is("speech","yes") || ask::Any("desktop")) {static char args[200];ReaderArguments(args,sizeof(args));   // r406: a desktop alone too (sign-in mode)
        // r409: CHARON_CHROOT=1 - curtin binds the installer's own /run into the chroot, so speech.sh cannot tell by itself
        // that nothing of the new system is running yet (it would "start" services and builds in the installer).
        y.Line("    - curtin in-target -- env CHARON_CHROOT=1 sh /var/lib/charon/speech.sh ",args," > /target/var/lib/charon/speech.log 2>&1 || true");}
    // r410 (kd): a step of a multi-system plan (CharonWsPlanDialogue.h InstallUbuntu sets the answer "plan"), as Debian's
    // late_command does (CharonWsInstall.h): the shared data partition's line, then the last act tells Charon that this
    // step is done (EFI/HAK/plan/stepN.done on the EFI partition the new system mounts at /boot/efi).
    if(ask::Any("plan")) {
        if(dataFstab && dataFstab[0])y.Line("    - mkdir -p /target/media/data; echo '",dataFstab,"' >> /target/etc/fstab; true");
        y.Line("    - curtin in-target -- sh /var/lib/charon/install-charon.sh plan-done || true");
    }
    if(ask::Is("speech","yes"))y.Line("    - sh /run/charon/live-speech.sh done; true");
    y.Line("  shutdown: reboot");
}
inline efi_status SetVolumeLabel(efi_handle volume,const char16_t* label) {
    static efi_guid labelGuid={0xdb47d7d3,0xfe81,0x11d3,{0x9a,0x35,0x00,0x90,0x27,0x3f,0xc1,0x4d}};
    efi_file_protocol* root=OpenRoot(volume);if(!root)return EFI_NOT_FOUND;
    static char16_t text[16];Set(text,12,label);
    const auto status=root->SetInfo(root,&labelGuid,(Len(text)+1)*2,text);
    root->Close(root);return status;
}
inline bool WriteText(efi_handle volume,const char16_t* path,const char* text,size_t size) {
    static FileRef ref;ref.volume=volume;Set(ref.path,pathUnits,path);
    return WriteWhole(ref,reinterpret_cast<const uint8_t*>(text),size)==EFI_SUCCESS;
}
// r409: Charon's voice and reader settings for the installed system (VoiceConf in CharonWsInstall.h).
inline bool WriteVoiceConf(efi_handle volume,const char16_t* path) {
    static char conf[512];const size_t n=VoiceConfNow(conf,sizeof(conf));
    return n && WriteText(volume,path,conf,n);
}
inline bool CopyReader(efi_handle volume,const char16_t* folder) {
    static const char16_t* const names[]={u"CHARONVOICE.EFI",u"AudioDxe.efi"};bool all=true;
    for(const auto* name:names) {
        static FileRef from,to;from.volume=U().host->selfDevice;Set(from.path,pathUnits,u"\\EFI\\HAK\\");Cat(from.path,pathUnits,name);
        to.volume=volume;if(!JoinPath(to.path,pathUnits,folder,name) || CopyFile(from,to)!=EFI_SUCCESS)all=false;
    }
    return all;
}
