// After the questions: which reader starts after sign-in. False: Escape.
inline bool ResolveWindowsReaders() {
    static Choice chosen[3];size_t n=0;
    for(const auto& c:windowsReaders)if(ask::Has("wreaders",c.value))chosen[n++]=c;
    ask::Put("speech",n?"yes":"no");
    if(n==0) {ask::Put("wfirst","none");return true;}
    if(n==1) {ask::Put("wfirst",chosen[0].value);return true;}
    // Narrator is part of Windows and is only switched on when nothing else is
    // chosen: it never competes with NVDA or JAWS, so only NVDA plus JAWS asks.
    const bool nvda=ask::Has("wreaders","nvda"),jaws=ask::Has("wreaders","jaws");
    if(!(nvda && jaws)) {ask::Put("wfirst",nvda?"nvda":"jaws");return true;}
    static const Choice names[]={{u"NVDA",u"NVDA","nvda"},{u"JAWS",u"JAWS","jaws"}};
    size_t i=0;
    if(!ask::Choose(T(u"Który czytnik ekranu ma się uruchamiać na ekranie logowania i po zalogowaniu? Drugi też zostanie zainstalowany.",
        u"Which screen reader should start on the sign-in screen and after sign-in? The other one is installed too."),names,2,i))return false;
    ask::Put("wfirst",names[i].value);
    return true;
}
// r407: what makes NVDA speak inside Windows Setup, into \charon\pe on the media: the unpacker, the
// stand-ins, the script the answer file runs and NVDA's configuration: the synthesizer is eSpeak NG
// (Setup's WinPE has no Windows voices). NVDA's language there, which also decides the eSpeak NG
// voice, is what @LANG@ stands for: English, and Polish only when the Windows being installed
// is Polish (the answer to "wlocale"); the language of Charon itself does not decide it.
constexpr const char* NvdaSetupLanguage(const char* windowsLocale) {
    return windowsLocale && (windowsLocale[0]=='p' || windowsLocale[0]=='P') && (windowsLocale[1]=='l' || windowsLocale[1]=='L')
        && (windowsLocale[2]==0 || windowsLocale[2]=='-' || windowsLocale[2]=='_')?"pl":"en";
}
static_assert(NvdaSetupLanguage("pl-PL")[0]=='p' && NvdaSetupLanguage("pl")[0]=='p',"Polish Windows: Polish NVDA in Setup");
static_assert(NvdaSetupLanguage("en-US")[0]=='e' && NvdaSetupLanguage("de-DE")[0]=='e' && NvdaSetupLanguage("")[0]=='e'
    && NvdaSetupLanguage(nullptr)[0]=='e' && NvdaSetupLanguage("plx")[0]=='e',"any other Windows: English NVDA in Setup");
inline bool NvdaSetupOntoMedia(efi_handle media) {
    ask::Put("nvdasetup","no");
    MakeFolders(media,u"\\charon\\pe");
    static FileRef to;to.volume=media;bool ok=true;
    struct Binary {const char16_t* path;const uint8_t* data;size_t size;};
    static const Binary binaries[]={{u"\\charon\\pe\\nvdape.exe",nvdaPeUnpack,sizeof(nvdaPeUnpack)},
        {u"\\charon\\pe\\pestub.dll",nvdaPeStub,sizeof(nvdaPeStub)},{u"\\charon\\pe\\pewait.exe",nvdaPeWait,sizeof(nvdaPeWait)},
        {u"\\charon\\pe\\peaudio.dll",nvdaPeAudio,sizeof(nvdaPeAudio)}};   // Setup plays only "alerts" sound: src/windows/peaudio.c
    for(const auto& b:binaries) {Set(to.path,pathUnits,b.path);if(WriteWhole(to,b.data,b.size)!=EFI_SUCCESS)ok=false;}
    const char* language=NvdaSetupLanguage(ask::Get("wlocale"));
    struct Script {const char16_t* path;const char* text;};
    static const Script scripts[]={{u"\\charon\\pe\\nvda-setup.cmd",nvdaPeScript},{u"\\charon\\pe\\nvda.ini",nvdaPeConfig},
        {u"\\charon\\pe\\charonpe.py",nvdaPeSynth}};
    static char out[8000];
    for(const auto& script:scripts) {
        Text t{out,sizeof(out),0,false};out[0]=0;
        for(const char* c=script.text;*c;) {
            if(c[0]=='@' && c[1]=='L' && c[2]=='A' && c[3]=='N' && c[4]=='G' && c[5]=='@') {t.Add(language);c+=6;}
            else {const char one[2]={*c++,0};t.Add(one);}
        }
        if(t.overflow || !WriteText(media,script.path,out,t.size))ok=false;
    }
    if(ok)ask::Put("nvdasetup","yes");
    return ok;
}
// NVDA for Setup and for the installed system: downloaded onto the install media, SHA-256 checked.
inline bool NvdaOntoMedia(efi_handle media) {
    // r410 (a plan that downloaded everything first, CharonWsPlanDialogue.h PlaceWindows): the file already lies on
    // the media with the pinned SHA-256 - nothing is downloaded. Any other content is fetched again, as before.
    {static FileRef there;there.volume=media;Set(there.path,pathUnits,u"\\charon\\readers\\");CatAscii(there.path,pathUnits,nvdaFile);
     uint8_t* have=nullptr;size_t size=0;
     if(ReadWhole(there,size_t(512)<<20,&have,&size)==EFI_SUCCESS && have) {
        Sha256 hash;hash.Update(have,size);uint8_t got[32];hash.Final(got);static const char hex[]="0123456789abcdef";Release(have);
        bool same=size!=0;for(int i=0;i<32 && same;++i)same=nvdaSha256[i*2]==hex[got[i]>>4] && nvdaSha256[i*2+1]==hex[got[i]&15];
        if(same) {
            ask::Put("nvdaready","yes");
            if(!NvdaSetupOntoMedia(media))
                Say(T(u"Uwaga: nie udało się zapisać na nośniku plików, które uruchamiają NVDA w instalatorze Windows; będzie w nim mówił Narrator.",
                      u"Note: the files that start NVDA in Windows Setup could not be saved to the media; Narrator will speak there instead."));
            return true;
        }
     }}
    if(!EnsureNetwork())return false;
    static Memory data;data.data=nullptr;data.capacity=0;data.size=0;data.extra=0;data.reserved=false;
    static FileRef none;none.volume=nullptr;none.path[0]=0;uint64_t received=0;
    Say(T(u"Pobieram NVDA na nośnik instalacyjny, żeby mówiło już w instalatorze Windows.",u"Downloading NVDA to the installation media, so that it speaks in Windows Setup already."));
    if(!net::DownloadAny(nvdaUrl,none,&received,&data,u"NVDA"))return false;
    Sha256 hash;hash.Update(data.data,data.size);uint8_t got[32];hash.Final(got);static const char hex[]="0123456789abcdef";
    bool same=true;for(int i=0;i<32 && same;++i)same=nvdaSha256[i*2]==hex[got[i]>>4] && nvdaSha256[i*2+1]==hex[got[i]&15];
    if(!same) {Free(data);Fail(T(u"Pobrany plik NVDA jest inny niż oczekiwany, więc go nie zapisano.",u"The downloaded NVDA file is not the expected one, so it was not saved."));return false;}
    MakeFolders(media,u"\\charon\\readers");
    static FileRef target;target.volume=media;Set(target.path,pathUnits,u"\\charon\\readers\\");CatAscii(target.path,pathUnits,nvdaFile);
    const efi_status st=WriteWhole(target,data.data,data.size);Free(data);
    if(st!=EFI_SUCCESS) {Fail(T(u"Nie udało się zapisać NVDA na nośniku.",u"NVDA could not be saved to the media."),st);return false;}
    ask::Put("nvdaready","yes");
    if(!NvdaSetupOntoMedia(media))   // r407
        Say(T(u"Uwaga: nie udało się zapisać na nośniku plików, które uruchamiają NVDA w instalatorze Windows; będzie w nim mówił Narrator.",
              u"Note: the files that start NVDA in Windows Setup could not be saved to the media; Narrator will speak there instead."));
    return true;
}
