// The system image Windows Setup installs from: \sources\install.wim, .esd or
// the first part of a split image. It must be a real image (WIM signature and
// a size no empty stand-in has), not just a name.
inline bool HasWindowsImage(efi_handle volume) {
    static const char16_t* const images[]={u"\\sources\\install.wim",u"\\sources\\install.esd",u"\\sources\\install.swm"};
    for(const auto* name:images) {
        efi_file_protocol* file=nullptr;FileRef ref;ref.volume=volume;Set(ref.path,pathUnits,name);
        if(OpenFile(ref,EFI_FILE_MODE_READ,0,&file)!=EFI_SUCCESS)continue;
        const auto* info=InfoOf(file);const uint64_t bytes=info?info->FileSize:0;
        uint8_t head[8]={};size_t got=sizeof(head);const bool read=file->Read(file,&got,head)==EFI_SUCCESS && got==sizeof(head);
        file->Close(file);
        static const uint8_t magic[8]={'M','S','W','I','M',0,0,0};bool wim=read;
        for(size_t k=0;k<8 && wim;++k)if(head[k]!=magic[k])wim=false;
        if(wim && bytes>=(uint64_t(256)<<20))return true;
    }
    return false;
}
// r406: how many system images (editions) the media's image file holds: the count stands in the WIM header.
inline unsigned WindowsImageCount(efi_handle volume) {
    static const char16_t* const images[]={u"\\sources\\install.wim",u"\\sources\\install.esd",u"\\sources\\install.swm"};
    for(const auto* name:images) {
        efi_file_protocol* file=nullptr;FileRef ref;ref.volume=volume;Set(ref.path,pathUnits,name);
        if(OpenFile(ref,EFI_FILE_MODE_READ,0,&file)!=EFI_SUCCESS)continue;
        uint8_t head[48]={};size_t got=sizeof(head);const bool read=file->Read(file,&got,head)==EFI_SUCCESS && got==sizeof(head);
        file->Close(file);
        if(read && head[0]=='M' && head[1]=='S' && head[2]=='W' && head[3]=='I' && head[4]=='M')
            return unsigned(head[44])|unsigned(head[45])<<8|unsigned(head[46])<<16|unsigned(head[47])<<24;
    }
    return 0;
}
// r406: a Windows product key in the firmware (ACPI table MSDM): Windows Setup chooses the edition by it.
inline bool FirmwareHasWindowsKey() {
    static const efi_guid acpi2={0x8868e871,0xe4f1,0x11d3,{0xbc,0x22,0x00,0x80,0xc7,0x3c,0x88,0x81}};
    auto* table=U().host->system;
    if(!table || !table->ConfigurationTable)return false;
    const uint8_t* rsdp=nullptr;
    for(size_t i=0;i<table->NumberOfTableEntries;++i) {
        const auto& entry=table->ConfigurationTable[i];const uint8_t* a=reinterpret_cast<const uint8_t*>(&entry);const uint8_t* b=reinterpret_cast<const uint8_t*>(&acpi2);
        bool same=true;for(size_t k=0;k<16;++k)if(a[k]!=b[k])same=false;
        if(same)rsdp=*reinterpret_cast<const uint8_t* const*>(a+16);
    }
    auto le32=[](const uint8_t* p) {return uint32_t(p[0]|p[1]<<8|p[2]<<16|uint32_t(p[3])<<24);};
    auto le64=[&](const uint8_t* p) {return uint64_t(le32(p))|(uint64_t(le32(p+4))<<32);};
    if(!rsdp || rsdp[0]!='R' || rsdp[1]!='S' || rsdp[15]<2)return false;
    const uint8_t* xsdt=reinterpret_cast<const uint8_t*>(uintptr_t(le64(rsdp+24)));
    if(!xsdt || xsdt[0]!='X')return false;
    const uint32_t length=le32(xsdt+4);
    for(uint32_t at=36;at+8<=length && at<36+8*256;at+=8) {
        const uint8_t* t=reinterpret_cast<const uint8_t*>(uintptr_t(le64(xsdt+at)));
        if(t && t[0]=='M' && t[1]=='S' && t[2]=='D' && t[3]=='M')return true;
    }
    return false;
}
// Windows install media: a volume with \sources\boot.wim, a boot manager AND the
// system image. A volume with only the boot manager (a recovery or test stick,
// a leftover EFI folder) is not install media: Charon writes nothing to it and
// does not start it. Such a volume is reported in bootOnly.
inline efi_handle& WindowsBootOnly() {static efi_handle volume=nullptr;return volume;}
inline bool FindWindowsMedia(efi_handle& media,bool& writable,const char16_t*& loader) {
    efi_handle volumes[32];const size_t n=Volumes(volumes,32);media=nullptr;WindowsBootOnly()=nullptr;
    // r401: the Windows boot manager under its own name first: on Charon's own
    // stick the removable-media loader (bootx64.efi) is Charon itself and must
    // never be taken for Windows.
    static const char16_t* const loaders[]={u"\\efi\\microsoft\\boot\\bootmgfw.efi",u"\\efi\\boot\\bootx64.efi"};
    for(size_t i=0;i<n && !media;++i) {
        efi_file_protocol* file=nullptr;FileRef ref;ref.volume=volumes[i];Set(ref.path,pathUnits,u"\\sources\\boot.wim");
        if(OpenFile(ref,EFI_FILE_MODE_READ,0,&file)!=EFI_SUCCESS)continue;
        file->Close(file);
        if(!HasWindowsImage(volumes[i])) {if(!WindowsBootOnly())WindowsBootOnly()=volumes[i];continue;}
        for(const auto* l:loaders) {
            if(l==loaders[1] && volumes[i]==U().host->selfDevice)continue;
            Set(ref.path,pathUnits,l);if(OpenFile(ref,EFI_FILE_MODE_READ,0,&file)==EFI_SUCCESS) {file->Close(file);media=volumes[i];loader=l;break;}}
    }
    if(media)writable=!VolumeReadOnly(media);
    return media!=nullptr;
}
inline void WindowsMediaMissing() {
    if(WindowsBootOnly()) {
        static char16_t label[64];static char16_t text[600];VolumeLabel(WindowsBootOnly(),label,64);
        Set(text,600,T(u"Nośnik ",u"The media "));Cat(text,600,label);
        Cat(text,600,T(u" ma tylko menedżer rozruchu Windows, bez obrazu systemu: brak pliku sources install wim albo install esd. To nie jest nośnik instalacyjny, więc Charon nic na nim nie zapisał i go nie uruchomi. Podłącz pendrive z pełnym instalatorem Windows 11.",
            u" holds only the Windows boot manager, with no system image: the file sources install wim or install esd is missing. It is not installation media, so Charon wrote nothing to it and will not start it. Plug in a USB stick with the complete Windows 11 installer."));
        Fail(text);return;
    }
    Fail(T(u"Nie znaleziono nośnika instalacyjnego Windows. Podłącz pendrive z instalatorem Windows 11 albo skopiuj zawartość obrazu ISO na partycję FAT32 i wybierz instalację ponownie.",
        u"No Windows installation media was found. Plug in a USB stick with the Windows 11 installer, or copy the contents of the ISO image to a FAT32 partition, and choose the installation again."));
}
// r409 (user): the installed Windows gets the network Charon uses, so nobody sets it up by hand. Ethernet needs
// nothing (Windows asks DHCP, as Charon did; Charon has no static address or proxy to pass on). Wi-Fi: the name and
// the password of the network Charon joined (net::Joined) are written to \charon\network.conf on the install
// media; at the first sign-in Charon-Network.ps1 makes a WLAN profile from it (netsh wlan add profile), connects and
// deletes the file (both copies). The password is NOT in the answer file, so it does not reach Setup's cached copy
// of it in Windows\Panther. Windows Setup itself (WinPE) has no Wi-Fi service: nothing in Charon's installation
// needs the network before the first sign-in (NVDA and Charon's files are on the media).
// Sets the answer "wnetwork" to yes when the file is on the media and the script is there to use it.
inline void WindowsNetworkOntoMedia(efi_handle media) {
    ask::Put("wnetwork","no");
    {static FileRef old;old.volume=media;Set(old.path,pathUnits,u"\\charon\\network.conf");efi_file_protocol* file=nullptr;   // a file of an earlier attempt never stays
     if(OpenFile(old,EFI_FILE_MODE_READ|EFI_FILE_MODE_WRITE,0,&file)==EFI_SUCCESS && file)file->Delete(file);}
    if(!net::Joined().valid)return;
    {static FileRef script;script.volume=U().host->selfDevice;Set(script.path,pathUnits,u"\\EFI\\HAK\\addon\\Charon-Network.ps1");efi_file_protocol* file=nullptr;
     if(OpenFile(script,EFI_FILE_MODE_READ,0,&file)!=EFI_SUCCESS || !file) {
        Say(T(u"Uwaga: na dysku Charona nie ma skryptu sieci, więc sieć Wi-Fi trzeba będzie ustawić w Windows ręcznie.",u"Note: Charon's disk has no network script, so Wi-Fi will have to be set up in Windows by hand."));return;}
     file->Close(file);}
    // The same text as for Linux (NetworkConfNow, CharonWsInstall.h: CHARON_WIFI_SSID, CHARON_WIFI_SECURITY, CHARON_WIFI_PSK).
    static char out[400];const size_t bytes=NetworkConfNow(out,sizeof(out));
    MakeFolders(media,u"\\charon");
    const bool ok=bytes && WriteText(media,u"\\charon\\network.conf",out,bytes);
    for(auto& c:out)c=0;
    if(ok)ask::Put("wnetwork","yes");
    else Say(T(u"Uwaga: nie udało się zapisać ustawień sieci Wi-Fi na nośniku; w Windows trzeba będzie połączyć się ręcznie.",u"Note: the Wi-Fi settings could not be saved to the media; in Windows the connection will have to be made by hand."));
}
